function A = dp_jacobian_apply(th1, om1, th2, om2, v1, v2, v3, v4, m1, m2, L1, L2, g)
%% DP_JACOBIAN_APPLY  Vectorised product  A = J(y) * v  for many states at once.
%%
%%   All arguments are 1xN row vectors (or scalars).  Returns A, 4xN.
%%
%%   GENERATED by dp_v2/gen/gen_jacobian_vectorised.py -- do not edit by hand.
%%
%%   WHY THIS EXISTS (performance, and it is the dominant cost)
%%   dp_jacobian.m builds a 4x4 matrix for a single state.  A grid sweep
%%   needs J*v for N states simultaneously; forming N matrices and calling
%%   pagemtimes on them is far slower than evaluating the four components
%%   directly.  Here the product is expanded symbolically, so the common
%%   denominator, its inverse and the shared trig terms are computed ONCE
%%   per row rather than once per state per RK4 stage.
%%
%%   The emitted expressions are algebraically identical to dp_jacobian;
%%   dp_v2/tests/test_core.m checks the two agree entry by entry.

    % --- common subexpressions ---
    s0 = th1 - th2;
    s1 = cos(s0);
    s2 = s1.^2;
    s3 = m1 + m2;
    s4 = m2.*s2 - s3;
    s5 = s4.^(-2);
    s6 = g.*s3;
    s7 = s6.*cos(th1);
    s8 = m2.*s2;
    s9 = L1.*om1.^2;
    s10 = L2.*om2.^2;
    s11 = s1.*s10;
    s12 = sin(th2);
    s13 = sin(s0);
    s14 = g.*s12.*s13;
    s15 = s13.^2;
    s16 = s15.*s9;
    s17 = s6.*sin(th1);
    s18 = m2.*s10;
    s19 = sin(2*th1 - 2*th2)/2;
    s20 = g.*s1;
    s21 = 2*s13;
    s22 = s1.*s21;
    s23 = s22.*(-m2.*s12.*s20 + m2.*s19.*s9 + s13.*s18 + s17);
    s24 = cos(th2);
    s25 = L2.*om2.*v4;
    s26 = L1.*om1.*v2;
    s27 = s21.*s4;
    s28 = s3.*s9;
    s29 = s1.*s28 + s10.*s8 - s13.*s17 - s15.*s18;
    s30 = m2.*s22;
    s31 = s30.*(s1.*s17 - s12.*s6 + s13.*s28 + s18.*s19);

    % --- A = J*v, componentwise ---
    A1 = v2;
    A2 = s5.*(m2.*s27.*(s1.*s26 + s25) - m2.*v3.*(s23 + s4.*(s11 + s14 - s16 + s2.*s9 + s20.*s24)) + v1.*(m2.*s23 + s4.*(m2.*s11 + m2.*s14 - m2.*s16 + s7 + s8.*s9)))./L1;
    A3 = v4;
    A4 = s5.*(-s25.*s30.*s4 - s26.*s27.*s3 - v1.*(s31 + s4.*(s1.*s7 + s29)) + v3.*(s31 + s4.*(s24.*s6 + s29)))./L2;

    A = [A1; A2; A3; A4];
end
